import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BXzK3EA4.js";const o="/assets/image%20(162).mVvoJZqC.png",n="/assets/image%20(163).MAKqVkVg.png",u=JSON.parse('{"title":"TradeSmart","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/tradesmart.md","filePath":"connect-brokers/brokers/tradesmart.md"}'),i={name:"connect-brokers/brokers/tradesmart.md"};function d(l,e,c,p,g,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="tradesmart" tabindex="-1">TradeSmart <a class="header-anchor" href="#tradesmart" aria-label="Permalink to &quot;TradeSmart&quot;">​</a></h1><p>TradeSmart is an Indian discount broker known for its flat-fee brokerage model that keeps trading costs low across equity, derivatives, and commodities. The platform offers fast order execution, real-time data, and a clean web and mobile experience. For automation, TradeSmart exposes a secure REST API built on the Noren v2 stack, letting you integrate it with Tradeboard using a generated App ID and Secret Key.</p><h3 id="getting-api-credentials" tabindex="-1">Getting API Credentials <a class="header-anchor" href="#getting-api-credentials" aria-label="Permalink to &quot;Getting API Credentials&quot;">​</a></h3><p>To integrate TradeSmart with Tradeboard, follow these steps to obtain your App ID and Secret Key:</p><ol><li>Log in to TradeSmart Web • Open <a href="https://web.tradesmartonline.in/login" target="_blank" rel="noreferrer">https://web.tradesmartonline.in/login</a> • <br> Enter your TradeSmart login credentials and your OTP/TOTP.</li><li>From the top right, open your Profile menu, expand <strong>Tools</strong>, and click <strong>API</strong>.</li></ol><figure><img src="'+o+'" alt=""><figcaption></figcaption></figure><ol start="3"><li><p>On the API Dashboard, if you have not set up TOTP yet, click <strong>Add/Setup TOTP</strong> at the top and complete the setup first. API access requires TOTP to be enabled.</p></li><li><p>In the <strong>Generate New API Key</strong> panel, fill out the form: <br></p><p>• <strong>Name</strong>: a label for the app, for example <code>Tradeboard</code> <br> • <strong>Primary IP Address</strong>: your static IP (required) <br> • <strong>Secondary IP Address</strong>: optional <br> • <strong>Redirect URL</strong>: <code>http://127.0.0.1:5000/tradesmart/callback</code> <br><br> Tick <strong>I acknowledge the API Terms &amp; Conditions</strong> and click <strong>Generate API Key</strong>.</p></li></ol><figure><img src="'+n+`" alt=""><figcaption></figcaption></figure><ol start="5"><li>Your new credential now appears under <strong>Active Credentials</strong>. Toggle <strong>Show Credentials</strong> to reveal the <strong>App ID</strong> and <strong>Secret Key</strong>, then copy both and start building!</li><li>Configure Tradeboard: • In your Tradeboard .env file, set the following variables:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BROKER_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;client_id:::api_key&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BROKER_API_SECRET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;secret_key&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">REDIRECT_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:5000/tradesmart/callback&#39;</span></span></code></pre></div><p>Where: • <code>client_id</code> is your TradeSmart login/client id (for example <code>YTNR739</code>) • <code>api_key</code> is the <strong>App ID</strong> generated on the dashboard • <code>secret_key</code> is the <strong>Secret Key</strong> revealed via the eye / Show Credentials toggle</p><blockquote><p>The Redirect URL in your .env must match the Redirect URL configured on the TradeSmart API Dashboard exactly, and your login IP must match the Primary Static IP you registered.</p></blockquote><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/tradesmart/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,15)])])}const k=t(i,[["render",d]]);export{u as __pageData,k as default};
